"""Isolated local JDP fixtures; real MQ pause, restart, refund-before-order and browser acceptance.
No refund approval, platform payment or warehouse operation is performed.
"""
import json,time,subprocess,urllib.parse
from pathlib import Path
from datetime import datetime,timedelta
from verify_goods_workspace_ui import login,request,BASE
from test_multi_virtual_shipping import sql,quote,wait_for
from verify_queue_management import docker,wait_health
OUT=Path(__file__).resolve().parents[2]/'outputs/refund-messaging';DB='qm_oms_saas_order';SRC='refund_acceptance_source'

def main():
 OUT.mkdir(parents=True,exist_ok=True);case={'stamp':datetime.now().strftime('%Y%m%d%H%M%S'),'checks':[]};token=login();original={}
 def save():(OUT/'case.json').write_text(json.dumps(case,ensure_ascii=False,indent=2),encoding='utf-8')
 def checked(label):case['checks'].append(label);save();print('PASS '+label,flush=True)
 def api(path,body=None,method=None):
  r=request(path,token=token,payload=body,method=method or ('POST' if body is not None else 'GET'));return r.get('data',r)
 def policy(kind):return api('/system/mqQueues/'+kind)
 def edit(kind,changes):r=policy(kind);r.update(changes);r['reason']='[退款队列验收] '+case['stamp'];return api('/system/mqQueues/'+kind,r,'PUT')
 def mode(kind,wanted):edit(kind,{'desired_mode':wanted});return wait_for(lambda:policy(kind),lambda r:r['effective_state']==wanted,'Queue did not apply: '+kind,240)
 def task(id):return api('/order/refunds/tasks/'+str(id))
 def refund(rid):return api('/order/refunds/platform?number='+rid)['rows'][0]
 def seed_refund(index,version=1,status='WAIT_SELLER_AGREE'):
  rid='96'+case['stamp']+str(index).zfill(3);modified=case['source_time'] if version==1 else datetime.now().strftime('%Y-%m-%d %H:%M:%S');p={'refund_id':rid,'tid':case['tid'],'oid':case['tid']+'1','seller_nick':case['seller'],'modified':modified,'refund_version':str(version),'refund_fee':'1.00','num':1,'status':status,'has_good_return':False,'reason':'[队列验收] 模拟申请，不执行退款'};payload=json.dumps({'refund_get_response':{'refund':p}},ensure_ascii=False)
  sql('INSERT INTO jdp_tb_refund(refund_id,tid,oid,status,seller_nick,created,modified,jdp_modified,jdp_response) VALUES ('+','.join(quote(v) for v in [rid,case['tid'],case['tid']+'1',status,case['seller'],modified,modified,modified,payload])+') ON DUPLICATE KEY UPDATE status=VALUES(status),modified=VALUES(modified),jdp_modified=VALUES(jdp_modified),jdp_response=VALUES(jdp_response)',SRC);return rid
 def pull_ids(ids,key):return api('/order/refunds/sync',{'channel_id':case['channel_id'],'mode':'IDS','refund_ids':ids,'request_key':key})['id']
 def messages(kind,number):return api('/order/messages?type='+kind+'&keyword='+number)['rows']
 def publish(envelope):
  body={'properties':{'delivery_mode':2,'content_type':'application/json','message_id':envelope['event_id']},'routing_key':envelope['message_type'],'payload':json.dumps(envelope),'payload_encoding':'string'}
  script="import sys,json,base64,urllib.request\nsys.path.insert(0,'docker/local')\nfrom local_db import ENV\nheaders={'Authorization':'Basic '+base64.b64encode((ENV['RABBITMQ_USER']+':'+ENV['RABBITMQ_PASSWORD']).encode()).decode(),'Content-Type':'application/json'}\nbody="+repr(body)+"\nr=urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:15672/api/exchanges/oms/oms.work.v1/publish',data=json.dumps(body).encode(),headers=headers),timeout=10)\nassert json.load(r)['routed']"
  result=subprocess.run(['wsl.exe','--','python3','-'],input=script.encode(),capture_output=True,timeout=20);assert result.returncode==0,'duplicate fixture publish failed'
 for service in ['oms-local-system','oms-local-channel','oms-local-order']:wait_health(service)
 try:
  original={k:policy(k) for k in ['REFUND_PULL','REFUND_CONVERT']};mode('REFUND_PULL','PAUSED');mode('REFUND_CONVERT','PAUSED')
  case['seller']='REFUND_QUEUE_'+case['stamp'];case['sku']='MQR'+case['stamp'];case['tid']='97'+case['stamp']+'01';name='[退款队列验收] '+case['stamp'];api('/channel/channel',{'channelName':name,'channelType':'TM','enabled':1,'toChannelEnabled':1,'syncEnabled':0,'mmodelType':1});ch=api('/channel/channel/list?channelName='+urllib.parse.quote(name))['rows'][0]['channelId'];case['channel_id']=ch;source=next(s for s in api('/order/orders/sources') if s['database_name']==SRC and s['enabled']);assert source['host']=='mysql';now=datetime.now();case['start']=(now-timedelta(hours=1)).strftime('%Y-%m-%d %H:%M:%S');case['end']=now.strftime('%Y-%m-%d %H:%M:%S');case['source_time']=(now-timedelta(minutes=10)).strftime('%Y-%m-%d %H:%M:%S');save()
  api('/order/refunds/configs',{'channel_id':ch,'source_key':source['source_key'],'seller_nick':case['seller'],'enabled':0,'auto_convert':1,'interval_seconds':30,'initial_time':case['start'],'revision':0})
  case['refund_ids']=[seed_refund(i) for i in range(1,52)];task_id=api('/order/refunds/sync',{'channel_id':ch,'mode':'MANUAL','start_time':case['start'],'end_time':case['end'],'request_key':'REFUND_PAGE_'+case['stamp']})['id'];case['page_task']=task_id;save();assert task(task_id)['message']['process_state']=='PENDING';assert sql('SELECT COUNT(*) FROM oms_platform_refund WHERE company_code=0x514d AND channel_id='+str(ch),DB)=='0';checked('paused refund pull retains task and does not read JDP')
  mode('REFUND_PULL','RUNNING');end=time.time()+120
  while time.time()<end:
   t=task(task_id)
   if int(t['synced_count'])>=50:break
   time.sleep(.15)
  assert int(t['synced_count'])==50,'first page not observed';case['checkpoint']=t['page_time'];docker('stop','--time','60','oms-local-order',timeout=90);assert sql('SELECT synced_count FROM oms_refund_sync WHERE company_code=0x514d AND id='+str(task_id),DB)=='50';docker('start','oms-local-order');wait_health('oms-local-order');wait_for(lambda:task(task_id),lambda r:r['state']=='COMPLETED','Refund pagination did not resume',180);assert int(task(task_id)['synced_count'])==51;assert sql('SELECT COUNT(*) FROM oms_refund WHERE company_code=0x514d AND channel_id='+str(ch),DB)=='0';checked('service restart resumes committed page and keeps source success separate from conversion')
  mode('REFUND_CONVERT','RUNNING');first=case['refund_ids'][0];wait_for(lambda:messages('REFUND_CONVERT',first),lambda r:r and r[0]['process_state']=='WAITING','Refund did not wait for original order',120);assert '等待原业务订单' in refund(first)['conversion_error'];case['waiting_refund_id']=first;checked('refund arriving before order waits without creating TK')
  # Create the original through the normal order source/pull/convert chain.
  sample=api('/goods/info/list?pageNum=1&pageSize=1',{})['rows'][0];sku=case['sku'];api('/goods/info',{'skuSn':sku,'goodsSn':sku,'goodsName':'[退款队列验收] '+sku,'categoryCode':sample['categoryCode'],'colorCode':sample['colorCode'],'sizeCode':sample['sizeCode'],'marketPrice':1,'validity':30,'isPackage':0,'isFd':0});api('/order/orders/configs',{'channel_id':ch,'source_key':source['source_key'],'seller_nick':case['seller'],'confirm_seller_mapping':1,'enabled':0,'auto_convert':1,'allowed_trade_types':['fixed'],'allow_public_stock':0,'interval_seconds':30,'initial_time':case['start']});trade={'tid':case['tid'],'status':'WAIT_SELLER_SEND_GOODS','type':'fixed','seller_nick':case['seller'],'oaid':'LOCAL-REFUND-QUEUE-TEST','payment':'100.00','orders':{'order':[{'oid':case['tid']+'1','num':100,'outer_sku_id':sku,'divide_order_fee':'100.00','title':'[退款队列验收] 商品'}]}};payload=json.dumps({'trade_fullinfo_get_response':{'trade':trade}},ensure_ascii=False);sql('INSERT INTO jdp_tb_trade(tid,status,type,seller_nick,created,modified,jdp_modified,jdp_response) VALUES ('+','.join(quote(v) for v in [case['tid'],'WAIT_SELLER_SEND_GOODS','fixed',case['seller'],case['source_time'],case['source_time'],case['source_time'],payload])+')',SRC);case['order_pull_task']=api('/order/orders/backfill',{'channel_ids':[ch],'mode':'TID','tids':[case['tid']],'request_key':'REFUND_ORDER_'+case['stamp']})['task_ids'][0];order=wait_for(lambda:api('/order/orders/platform/list?tid='+case['tid'])['rows'],lambda r:r and r[0]['business_order_id'],'Original order conversion did not complete',180)[0];case['order_id']=order['business_order_id'];case['order_sn']=api('/order/orders/business/'+str(case['order_id']))['order_sn'];wait_for(lambda:sql('SELECT COUNT(*) FROM oms_refund WHERE company_code=0x514d AND channel_id='+str(ch),DB),lambda n:n=='51','Refunds did not link to original order',240);r=refund(first);case['platform_id']=r['id'];case['business_refund_id']=r['business_refund_id'];case['refund_sn']=api('/order/refunds/business/'+str(r['business_refund_id']))['refund_sn'];case['convert_event']=messages('REFUND_CONVERT',first)[0]['event_id'];checked('51 independent refund identities link to the same original order with no approval or money action')
  before=sql('SELECT COUNT(*) FROM oms_refund_event WHERE company_code=0x514d AND action=\'CONVERT\' AND refund_id='+str(r['business_refund_id']),DB);publish(api('/order/messages/'+case['convert_event'])['envelope']);time.sleep(3);assert before==sql('SELECT COUNT(*) FROM oms_refund_event WHERE company_code=0x514d AND action=\'CONVERT\' AND refund_id='+str(r['business_refund_id']),DB);repull=pull_ids([first],'REFUND_REPEAT_'+case['stamp']);case['repeat_task']=repull;wait_for(lambda:task(repull),lambda r:r['state']=='COMPLETED','Refund ID re-pull failed',120);assert sql('SELECT COUNT(*) FROM oms_refund WHERE company_code=0x514d AND channel_id='+str(ch),DB)=='51';checked('duplicate MQ delivery and specified refund ID re-pull cannot duplicate TK')
  mode('REFUND_CONVERT','PAUSED');closing=seed_refund(52);t=pull_ids([closing],'REFUND_CLOSE1_'+case['stamp']);wait_for(lambda:task(t),lambda r:r['state']=='COMPLETED','Close fixture first pull failed',120);seed_refund(52,2,'CLOSED');t=pull_ids([closing],'REFUND_CLOSE2_'+case['stamp']);wait_for(lambda:task(t),lambda r:r['state']=='COMPLETED','Close fixture update pull failed',120);mode('REFUND_CONVERT','RUNNING');wait_for(lambda:refund(closing),lambda r:r['conversion_state']=='SKIPPED','Closed refund incorrectly converted',120);assert refund(closing)['business_refund_id'] is None;case['closed_refund_id']=closing;checked('newer platform closure invalidates queued old conversion without creating TK')
  # Explicit conversion remains available when automatic conversion is disabled.
  config=next(c for c in api('/order/refunds/configs')['configs'] if int(c['channel_id'])==int(ch));config.update({'enabled':0,'auto_convert':0});api('/order/refunds/configs',config);manual=seed_refund(53);t=pull_ids([manual],'REFUND_MANUAL_'+case['stamp']);wait_for(lambda:task(t),lambda r:r['state']=='COMPLETED','Manual source pull failed',120);p=refund(manual);assert not p['message'];api('/order/refunds/platform/'+str(p['id'])+'/convert',{});wait_for(lambda:refund(manual),lambda r:r['conversion_state']=='SUCCESS','Explicit manual queue conversion failed',120);checked('manual conversion uses queue even when automatic conversion is disabled')
  from playwright.sync_api import sync_playwright,expect
  with sync_playwright() as playwright:
   browser=playwright.chromium.launch(headless=True);ctx=browser.new_context(viewport={'width':1800,'height':1100});ctx.add_cookies([{'name':'Admin-Token','value':token,'url':BASE}]);page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(BASE+'/oms-order/management?tab=tasks&kind=REFUND&taskId='+str(task_id),wait_until='networkidle');expect(page.get_by_placeholder('配合业务类型精确查询')).to_have_value(str(task_id));page.get_by_role('button',name='查看消息链路',exact=True).first.click();expect(page.get_by_placeholder('全部业务类型')).to_have_value('退款拉取');page.screenshot(path=str(OUT/'pull-chain.png'),full_page=True,animations='disabled');page.locator('.el-table__fixed-right').get_by_role('button',name='详情 / 链路',exact=True).first.click();page.locator('.el-drawer:visible').get_by_role('button',name='打开业务单据',exact=True).click();expect(page.get_by_placeholder('配合业务类型精确查询')).to_have_value(str(task_id));page.goto(BASE+'/monitor/messages?service=order&type=REFUND_CONVERT&event='+case['convert_event'],wait_until='networkidle');page.locator('.el-table__fixed-right').get_by_role('button',name='详情 / 链路',exact=True).first.click();page.locator('.el-drawer:visible').get_by_role('button',name='打开业务单据',exact=True).click();expect(page.locator('.platform-documents')).to_be_visible();expect(page.get_by_role('button',name='查看消息链路',exact=True).first).to_be_visible();page.screenshot(path=str(OUT/'platform-conversion.png'),full_page=True,animations='disabled');assert not errors,errors;browser.close()
  checked('browser source task and platform refund expose progress and bidirectional message links');case['queues']=[{k:r[k] for k in ['business_type','effective_state','actual_consumers']} for r in api('/system/mqQueues')['queues']];save()
 finally:
  docker('start','oms-local-order');wait_health('oms-local-order')
  for kind,r in original.items():edit(kind,{k:r[k] for k in ['desired_mode','concurrency','prefetch','retry_limit','retry_base_sec','retry_max_sec','compensate_after_sec','compensate_batch','app_rate','shop_rate','alarm_backlog','alarm_due_sec','alarm_failure_pct']})
 print('PASS refund messaging acceptance retained: outputs/refund-messaging/case.json',flush=True)
if __name__=='__main__':main()
